from .errors import TabulaError, UsageError

PROG = "tabula"
FORMATS = ("text", "csv", "json")
# The choice options every command line accepts: name -> allowed values; the first-listed default is in DEFAULTS.
CHOICES = {"format": FORMATS, "kind": ("inner", "left"), "keep": ("first", "last")}
DEFAULTS = {"format": "text", "kind": "inner", "keep": "first"}
getcontext().prec = 60

NUMBER = re.compile(r"[+-]?(?:\d+(?:\.\d*)?|\.\d+)")


