        try:
            os.dup2(os.open(os.devnull, os.O_WRONLY), sys.stdout.fileno())
        except (OSError, ValueError):
            pass
        print("%s: cannot write output: %s" % (PROG, exc.strerror or exc), file=sys.stderr)
        return 1
"""The sort command: the engine function and the command line through `python -m tabula`."""
import os, subprocess, sys, tempfile, unittest

ROOT = os.path.join(os.path.dirname(os.path.abspath(__file__)), "..")
sys.path.insert(0, ROOT)
from tabula import engine
from tabula.errors import TabulaError, UsageError

FILES = {
    "p.csv": "name,price,city\nb,10,x\nB,9,y\na,10.50,x\nc,abc,y\n",
    "n.csv": "name,price\nb,10\nB,9\na,10.50\nd,-1\ne,+9.0\n",
    "ties.csv": "k,id\na,1\nb,2\na,3\nb,4\n",
    "m.csv": "g,n\nx,2\ny,1\nx,1\ny,2\n",
    "dash.csv": "a,-b\nx,2\ny,1\n",
    "e.csv": "name,price\nb,3\na,\n",
}


def run_cli(*argv):
    with tempfile.TemporaryDirectory() as d:
        for k, v in FILES.items():
            with open(os.path.join(d, k), "w", encoding="utf-8", newline="") as fh:
                fh.write(v)
        env = dict(os.environ, PYTHONPATH=ROOT)
        p = subprocess.run([sys.executable, "-m", "tabula"] + list(argv), cwd=d, env=env, capture_output=True, text=True)
        return p.returncode, p.stdout, p.stderr


def sort_in(name, *keys):
    with tempfile.TemporaryDirectory() as d:
        path = os.path.join(d, name)
        with open(path, "w", encoding="utf-8", newline="") as fh:
            fh.write(FILES[name])
        return engine.cmd_sort([path] + list(keys), dict(engine.DEFAULTS)).rows


class SortEngineTests(unittest.TestCase):
    def test_orders(self):
        for name, keys, first_col, expected in [
            ("n.csv", ["name"], 0, ["B", "a", "b", "d", "e"]),
            ("n.csv", ["name:desc"], 0, ["e", "d", "b", "a", "B"]),
            ("n.csv", ["price"], 0, ["e", "d", "b", "a", "B"]),
            ("n.csv", ["price:num"], 0, ["d", "B", "e", "b", "a"]),
            ("n.csv", ["price:num:desc"], 0, ["a", "b", "B", "e", "d"]),
            ("n.csv", ["price:desc:num"], 0, ["a", "b", "B", "e", "d"]),
            ("ties.csv", ["k"], 1, ["1", "3", "2", "4"]),
            ("ties.csv", ["k:desc"], 1, ["2", "4", "1", "3"]),
            ("m.csv", ["g", "n:num"], 1, ["1", "2", "1", "2"]),
            ("m.csv", ["g:desc", "n:num:desc"], 1, ["2", "1", "2", "1"]),
        ]:
            with self.subTest(name=name, keys=keys):
                rows = sort_in(name, *keys)
                self.assertEqual([r[first_col] for r in rows], expected)

    def test_code_point_order(self):
        self.assertEqual([r[0] for r in sort_in("p.csv", "name")], ["B", "a", "b", "c"])

    def test_row_numbers_are_file_order(self):
        with self.assertRaises(TabulaError) as cm:
            sort_in("p.csv", "price:num")

